"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[36366],{36366:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/68993a6a8faeacf5320362107be65314.jpg\\"\\n  title=\\"Song Fa Bak Kut Teh at HarbourFront Centre\\"\\n  cuisine=\\"Southeast Asian\\"\\n  address=\\"1 Maritime Square, Singapore 099253\\"\\n  rating=4\\n  tags=\\"restaurant\\"\\n/>\\n</center>\\n\\n## Review\\nSince the main branch of Song Fa Bak Kut Teh is often crowded and described as less pleasant, I headed to this cleaner branch.  \\n\\nBeing located inside a mall, the interior was definitely comfortable and cool.  \\nThere was a wait, but I was able to enter without waiting too long.  \\n\\nThe taste was familiar, similar to Korean Galbi-tang.  \\nThe broth is a bit clearer and oilier than Galbi-tang, but the strong garlic and pepper notes made it very enjoyable.  \\n\\nThe soup is refillable, and rice must be ordered separately."}')}}]);